// UtilsServiceServer is the server API for UtilsService service.
type UtilsServiceServer interface {
	// FindPhysicalKeyboard finds /dev/input/event* file for physical a keyboard.
	FindPhysicalKeyboard(context.Context, *emptypb.Empty) (*InputDevicePath, error)
	// FindPowerKeyDevice finds /dev/input/event* file for device that reads power
	// key keycodes.
	FindPowerKeyDevice(context.Context, *emptypb.Empty) (*InputDevicePath, error)
	// NewChrome creates a new instance of Chrome
	NewChrome(context.Context, *emptypb.Empty) (*emptypb.Empty, error)
	// CloseChrome closes an existing instance of Chrome
	CloseChrome(context.Context, *emptypb.Empty) (*emptypb.Empty, error)
	// ReuseChrome passes an Option to New to make Chrome reuse an exisiting
	// Chrome session.
	ReuseChrome(context.Context, *emptypb.Empty) (*emptypb.Empty, error)
	// EvalTabletMode evaluates if DUT is in tablet mode.
	EvalTabletMode(context.Context, *emptypb.Empty) (*EvalTabletModeResponse, error)
	// FindSingleNode finds the specific UI node based on the passed in element.
	FindSingleNode(context.Context, *NodeElement) (*emptypb.Empty, error)
	// GetDetachableBaseValue retrieves the values of relevant detachable-base
	// properties.
	GetDetachableBaseValue(context.Context, *emptypb.Empty) (*CrosConfigResponse, error)
	// PerformSpeedometerTest opens a speedometer test website, runs it and
	// returns the result value.
	PerformSpeedometerTest(context.Context, *emptypb.Empty) (*SpeedometerResponse, error)
	// CheckCrosConfigProperty checks cros_config and returns the value of a
	// hardware property.
	CheckCrosConfigProperty(context.Context, *CheckCrosConfigRequest) (*CheckCrosConfigResponse, error)
	// FlashUSBDrive flashes the attached USB drive with a ChromeOS test image.
	FlashUSBDrive(context.Context, *FlashUSBDriveRequest) (*emptypb.Empty, error)
	// FirmwareBuildTargets returns the names of the firmware targets from the
	// cros config yaml file.
	FirmwareBuildTargets(context.Context, *FirmwareBuildTargetsRequest) (*FirmwareBuildTargetsResponse, error)
	// ExtractAPFirmwareImage downloads and extracts the AP image from devservers.
	ExtractAPFirmwareImage(context.Context, *ExtractFirmwareImageRequest) (*ExtractFirmwareImageResponse, error)
	// ExtractECFirmwareImage downloads and extracts the EC image from devservers.
	ExtractECFirmwareImage(context.Context, *ExtractFirmwareImageRequest) (*ExtractFirmwareImageResponse, error)
}

